ALTER TABLE public.foreign_work_country_evidence ADD CONSTRAINT fw_evidence_destination_valid CHECK(public.country_iso(destination_country) IS NOT NULL), ADD CONSTRAINT fw_evidence_home_valid CHECK(public.country_iso(home_country) IS NOT NULL);
CREATE OR REPLACE FUNCTION public.guard_installer_home_country() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.home_country IS DISTINCT FROM OLD.home_country THEN IF auth.uid() IS NOT NULL AND NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr')) THEN RAISE EXCEPTION 'Endast admin eller HR kan ändra hemland' USING ERRCODE='42501'; END IF; IF NEW.home_country IS NOT NULL AND (public.country_iso(NEW.home_country) IS NULL OR public.country_iso(NEW.home_country)<>NEW.home_country) THEN RAISE EXCEPTION 'Hemland måste vara en giltig landskod'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.set_installer_home_country(_installer_id uuid,_country text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr')) THEN RAISE EXCEPTION 'Endast admin eller HR kan ändra hemland' USING ERRCODE='42501'; END IF; IF _country IS NOT NULL AND public.country_iso(_country) IS NULL THEN RAISE EXCEPTION 'Okänt land'; END IF; UPDATE public.installers SET home_country=public.country_iso(_country) WHERE id=_installer_id; END $$;
CREATE OR REPLACE FUNCTION public.capture_foreign_time_country() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.foreign_work_country_evidence(time_entry_id,installer_id,project_id,destination_country,home_country,reason) SELECT NEW.id,NEW.installer_id,p.id,p.country_code,i.home_country,'Ny tidspost på slutförd order med bekräftat land' FROM public.projects p JOIN public.installers i ON i.id=NEW.installer_id WHERE p.id=NEW.project_id AND p.status='completed' AND p.country_provenance='CONFIRMED' AND p.country_code IS NOT NULL AND public.country_iso(i.home_country)=i.home_country AND NEW.hours>0 AND NOT EXISTS(SELECT 1 FROM public.foreign_work_country_evidence e WHERE e.time_entry_id=NEW.id AND e.voided_at IS NULL); RETURN NEW; END $$;
CREATE TRIGGER fw_capture_new_time_country AFTER INSERT ON public.time_entries FOR EACH ROW EXECUTE FUNCTION public.capture_foreign_time_country();
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.foreign_work_days(date,date,uuid)'::regprocedure); IF strpos(d,'COALESCE(e.home_country,i.home_country)')=0 THEN RAISE EXCEPTION 'Unexpected foreign_work_days definition'; END IF; d:=replace(d,'COALESCE(e.home_country,i.home_country)','COALESCE(e.home_country,public.country_iso(i.home_country))'); d:=replace(d,'r.country IS NULL OR r.home IS NULL OR r.project_id IS NULL THEN','r.country IS NULL OR r.home IS NULL OR r.project_id IS NULL OR (r.country=r.home AND NOT r.frozen AND r.country_provenance<>''CONFIRMED'') THEN'); d:=replace(d,'r.country<>r.home GROUP BY','r.country<>r.home OR (r.country=r.home AND NOT r.frozen AND r.country_provenance<>''CONFIRMED'') GROUP BY'); d:=replace(d,'a.work AND a.verified THEN ''time_entry_completed''','a.work AND a.verified THEN ''time_entry_completed'''); d:=replace(d,'ELSE ''unresolved_time'' END','ELSE CASE WHEN a.country=''UNKNOWN'' THEN ''unresolved_time'' ELSE ''travel_only'' END END'); d:=replace(d,'a.country=''UNKNOWN'' OR a.insufficient THEN','a.country=''UNKNOWN'' OR a.insufficient OR (NOT COALESCE(a.work,false) AND NOT COALESCE(a.manual_work,false) AND NOT COALESCE(a.any_presence,false)) THEN'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.foreign_work_my_documents(_installer_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'installer') OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr')) THEN RAISE EXCEPTION 'Staff only' USING ERRCODE='42501'; END IF; IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'hr')) AND _installer_id IS DISTINCT FROM public.current_installer_id() THEN RAISE EXCEPTION 'Own summary only' USING ERRCODE='42501'; END IF; SELECT COALESCE(jsonb_agg(jsonb_build_object('id',d.id,'installer_id',d.installer_id,'doc_type',d.doc_type,'countries',d.countries,'valid_from',d.valid_from,'valid_to',d.valid_to,'status',d.status,'reference_number',NULL,'notes',NULL,'voided_at',NULL)),'[]') INTO v FROM public.foreign_work_documents d WHERE d.installer_id=_installer_id AND d.voided_at IS NULL; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.foreign_work_my_documents(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.foreign_work_my_documents(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.correct_foreign_work_period(_id uuid,_values jsonb,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.foreign_work_periods; v uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only' USING ERRCODE='42501'; END IF; IF length(btrim(COALESCE(_reason,'')))<3 THEN RAISE EXCEPTION 'Rättningsskäl krävs'; END IF; SELECT * INTO e FROM public.foreign_work_periods WHERE id=_id AND voided_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Aktiv period saknas'; END IF; UPDATE public.foreign_work_periods SET voided_at=now(),void_reason=_reason,verification_status='VOIDED' WHERE id=e.id; INSERT INTO public.foreign_work_periods(installer_id,project_id,country,start_at,end_at,kind,source,verification_status,notes,corrects_id) VALUES(COALESCE((_values->>'installer_id')::uuid,e.installer_id),e.project_id,COALESCE(_values->>'country',e.country),COALESCE((_values->>'start_at')::timestamptz,e.start_at),COALESCE((_values->>'end_at')::timestamptz,e.end_at),COALESCE(_values->>'kind',e.kind),'approved_correction','MANUALLY_CONFIRMED',COALESCE(_values->>'notes',e.notes)||' – '||_reason,e.id) RETURNING id INTO v; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.correct_foreign_work_period(uuid,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.correct_foreign_work_period(uuid,jsonb,text) TO authenticated;